mapper.select:
SELECT id, name, price, stock, status, category_id
FROM product
WHERE id = #{id}

mapper.update:
UPDATE product
SET name = #{request.name}, price = #{request.price}, category_id = #{request.categoryId}
WHERE id = #{id}

UPDATE product
SET stock = stock - #{quantity}
WHERE id = #{id} AND status = 'ON_SALE' AND stock >= #{quantity}

UPDATE product
SET status = #{status}
WHERE id = #{id}

UPDATE product
SET stock = stock + #{quantity}
WHERE id = #{id}

mapper.sql:
WHERE p.status = 'ON_SALE'

    AND p.category_id = #{categoryId}


    AND p.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!'

mapper.select:
SELECT p.id, p.name, p.price, p.stock, p.status, p.category_id, c.name AS category_name
FROM product p LEFT JOIN product_category c ON c.id=p.category_id

ORDER BY p.id ASC LIMIT #{limit} OFFSET #{offset}
